  `operator` varchar(100) NOT NULL COMMENT 'kto scanoval',
  `timestamp` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `item_id` (`item_id`),
  KEY `shelf_id` (`shelf_id`)
