CREATE TABLE `order_items` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) NOT NULL,
  `line_no` int(11) DEFAULT NULL,
  `sku` varchar(128) DEFAULT NULL,
